// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Список едоков
	// (GET /eaters)
	ListEaters(w http.ResponseWriter, r *http.Request)
	// Создать профиль едока
	// (POST /eaters)
	CreateEater(w http.ResponseWriter, r *http.Request)
	// Профиль едока
	// (GET /eaters/{eaterId})
	GetEater(w http.ResponseWriter, r *http.Request, eaterId EaterId)
	// Обновить профиль (влияет на следующую генерацию, не на существующие планы)
	// (PUT /eaters/{eaterId})
	UpdateEater(w http.ResponseWriter, r *http.Request, eaterId EaterId)
	// Личные исключения едока (preference bans, напр. морепродукты)
	// (GET /eaters/{eaterId}/exclusions)
	ListExclusions(w http.ResponseWriter, r *http.Request, eaterId EaterId)
	// Добавить исключение по предпочтению (hard/soft, по food_group/role_tag/product)
	// (POST /eaters/{eaterId}/exclusions)
	CreateExclusion(w http.ResponseWriter, r *http.Request, eaterId EaterId)
	// Фиксированные приёмы пищи едока (напр. Сашин завтрак)
	// (GET /eaters/{eaterId}/fixed-meals)
	ListFixedMeals(w http.ResponseWriter, r *http.Request, eaterId EaterId)
	// Добавить фиксированный приём (учитывается в БЖУ, не генерируется)
	// (POST /eaters/{eaterId}/fixed-meals)
	CreateFixedMeal(w http.ResponseWriter, r *http.Request, eaterId EaterId)
	// История целей по БЖУ (от новых к старым)
	// (GET /eaters/{eaterId}/goals)
	ListEaterGoals(w http.ResponseWriter, r *http.Request, eaterId EaterId)
	// Задать новую цель (создаёт версию, не перезаписывает прошлые)
	// (POST /eaters/{eaterId}/goals)
	CreateEaterGoal(w http.ResponseWriter, r *http.Request, eaterId EaterId)
	// Удалить исключение
	// (DELETE /exclusions/{exclusionId})
	DeleteExclusion(w http.ResponseWriter, r *http.Request, exclusionId int64)
	// Список продуктов
	// (GET /products)
	ListProducts(w http.ResponseWriter, r *http.Request, params ListProductsParams)
	// Добавить продукт в личную БД
	// (POST /products)
	CreateProduct(w http.ResponseWriter, r *http.Request)
	// Удалить продукт
	// (DELETE /products/{productId})
	DeleteProduct(w http.ResponseWriter, r *http.Request, productId ProductId)
	// Продукт
	// (GET /products/{productId})
	GetProduct(w http.ResponseWriter, r *http.Request, productId ProductId)
	// Обновить продукт
	// (PUT /products/{productId})
	UpdateProduct(w http.ResponseWriter, r *http.Request, productId ProductId)
	// Библиотека рецептов-шаблонов
	// (GET /recipes)
	ListRecipes(w http.ResponseWriter, r *http.Request, params ListRecipesParams)
	// Создать рецепт-шаблон вручную (status=draft по умолчанию)
	// (POST /recipes)
	CreateRecipe(w http.ResponseWriter, r *http.Request)
	// Рецепт-шаблон со слотами
	// (GET /recipes/{recipeId})
	GetRecipe(w http.ResponseWriter, r *http.Request, recipeId RecipeId)
	// Повысить draft → permanent после реальной готовки + одобрения (FR-9)
	// (POST /recipes/{recipeId}/promote)
	PromoteRecipe(w http.ResponseWriter, r *http.Request, recipeId RecipeId)
	// Справочник ролевых тегов (с подклассами)
	// (GET /role-tags)
	ListRoleTags(w http.ResponseWriter, r *http.Request)
}

